            factors.append(d)
            n //= d
        d += 2

    if n > 1:
        fa

def deep_get_path(data, keys: list, default=None):
    """Walk a nested structure recursively following *keys*, returning *default* when a
    step is missing or the current value is not a dict. An empty key list returns the
    data itself.
    """
    if not keys:
        return data
    if not isinstance(data, dict):
        return default
    key = keys[0]
    if key not in data:
        return default
    return deep_get_path(data[key], keys[1:], default)

def permutations_of(items: list) -> list:
    """Return every permutation of *items* as a list of tuples, sorted ascending, using
    recursion and without itertools. An empty input gives [()].
    """
    if not items:
        return [()]

    result = []
    for i, item in enumerate(items):
        remaining = items[:i] + items[i + 1:]
        for tail in permutations_of(remaining):
            result.append((item,) + tail)

    return sorted(result)

def count_down(n: int) -> list:
    """Return [n, n-1, ..., 1] using recursion. A non-positive n gives an empty list.
    """
    if n <= 0:
        return []
    return [n] + count_down(n - 1)

def lcs_length(a: str, b: str) -> int:
    """Return the length of the longest common subsequence of two strings.
    """
    if len(a) < len(b):
        a, b = b, a

    prev = [0] * (len(b) + 1)

    for ca in a:
        curr = [0] * (len(b) + 1)
        for j, cb in enumerate(b, 1):
            if ca == cb:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr

    return prev[-1]

def first_matching(items: list, prefix: str):
    """Return the first string in *items* that starts with *prefix*, or None when there is
    none. Non-string elements are skipped.
    """
    for item in items:
        if isinstance(item, str) and item.startswith(prefix):
            return item
    return None

def average(numbers):
    """Return the mean of *numbers*, or 0.0 when the list is empty."""
    if not numbers:
        return 0.0
    return sum(numbers) / len(numbers)

def count_up(n):
    """Return [1, 2, ..., n]."""
    return list(range(1, n + 1))

def starts_with_vowel(word):
    """Return True when *word* starts with a, e, i, o or u, ignoring case."""
    return word[:1].lower() in 'aeiou'

def percentage(part, whole):
    """Return part as a percentage of whole, or 0.0 when whole is 0."""
    if whole == 0:
        return 0.0
    return part / whole * 100

def last_element(items):
    """Return the last element, or None when the list is empty."""
    if not items:
        return None
    return items[-1]

def merge_configs(defaults, overrides):
    """Return a new dict of *defaults* updated with *overrides*, leaving both inputs alone."""
    return {**defaults, **overrides}

def find_index(items, target):
    """Return the index of the first occurrence of *target*, or -1."""
    for i, item in enumerate(items):
        if item == target:
            return i
    return -1

def title_case(text):
    """Capitalise every word, treating both spaces and hyphens as separators."""
    return ' '.join(
        '-'.join(part.capitalize() for part in word.split('-'))
        for word in text.split(' ')
    )

def running_max(numbers):
    """Return the running maximum: element i is max(numbers[0..i])."""
    out = []
    best = None
    for x in numbers:
        if best is None or x > best:
            best = x
        out.append(best)
    return out

def dedupe(items):
    """Remove duplicates, keeping the first occurrence of each value in order."""
    return list(dict.fromkeys(items))

def clamp_value(value, low, high):
    """Return *value* limited to [low, high]."""
    return max(low, min(value, high))

def count_matches(items, predicate_value):
    """Count how many elements equal *predicate_value*."""
    total = 0
    for item in items:
        if item == predicate_value:
            total += 1
    return total

def chunk_list(items, size):
    """Split *items* into lists of at most *size* elements."""
    return [items[i:i + size] for i in range(0, len(items), size)]

def strip_prefix(text, prefix):
    """Remove *prefix* from the start of *text* if it is there, otherwise return *text*."""
    if text.startswith(prefix):
        return text[len(prefix):]
    return text

def sum_positive(numbers):
    """Add up every number greater than 0, skipping the rest."""
    total = 0
    for x in numbers:
        if x <= 0:
            continue
        total += x
    return total

def is_sorted(numbers):
    """Return True when *numbers* is non-decreasing."""
    for i in range(len(numbers) - 1):
        if numbers[i] > numbers[i + 1]:
            return False
    return True

def word_lengths(text):
    """Return the length of every word, ignoring leading and trailing . , ! and ?"""
    return [len(w.strip('.,!?')) for w in text.split()]
